func expandE2M1(ctx context.Context, p path.Path, m *E2MModel, diags *diag.Diagnostics) *events2metrics_service.E2M1 {
	if m == nil {
		return nil
	}
	out := &events2metrics_service.E2M1{}
	out.DataSource = expandString(m.DataSource)
	if m.Description.IsNull() {
		// The API keeps a stored value that the request omits, so a removed value is sent as "".
		out.Description = new(string)
	} else {
		out.Description = expandString(m.Description)
	}
	out.LogsQuery = expandV2LogsQuery(ctx, p.AtName("logs_query"), m.LogsQuery, diags)
	if items := expandMap[V2MetricFieldModel](ctx, p.AtName("metric_fields"), m.MetricFields, diags); items != nil {
		out.MetricFields = make([]events2metrics_service.V2MetricField, 0, len(items))
		for _, k := range slices.Sorted(maps.Keys(items)) {
			item := items[k]
			v := *expandV2MetricField(ctx, p.AtName("metric_fields").AtMapKey(k), &item, diags)
			v.TargetBaseMetricName = k
			out.MetricFields = append(out.MetricFields, v)
		}
	}
	if items := expandMap[string](ctx, p.AtName("metric_labels"), m.MetricLabels, diags); items != nil {
		out.MetricLabels = make([]events2metrics_service.MetricLabel, 0, len(items))
		for _, k := range slices.Sorted(maps.Keys(items)) {
			v := items[k]
			out.MetricLabels = append(out.MetricLabels, events2metrics_service.MetricLabel{TargetLabel: k, SourceField: v})
		}
	}
	out.Name = valueOf(expandString(m.Name))
	if v := m.Permutations; !v.IsNull() && !v.IsUnknown() {
		var nested E2MPermutationsModel
		diags.Append(v.As(ctx, &nested, basetypes.ObjectAsOptions{})...)
		out.Permutations = expandE2MPermutations(ctx, p.AtName("permutations"), &nested, diags)
	}
	out.SpansQuery = expandV2SpansQuery(ctx, p.AtName("spans_query"), m.SpansQuery, diags)
	switch {
	case m.LogsQuery != nil:
		fixed := events2metrics_service.E2MType("E2M_TYPE_LOGS2METRICS")
		out.Type = fixed
	case m.SpansQuery != nil:
		fixed := events2metrics_service.E2MType("E2M_TYPE_SPANS2METRICS")
		out.Type = fixed
	}
	return out
}

