func flattenE2M(ctx context.Context, p path.Path, v *events2metrics_service.E2M, prior *E2MModel, diags *diag.Diagnostics) *E2MModel {
	if v == nil {
		return nil
	}
	out := &E2MModel{}
	out.DataSource = types.StringPointerValue(v.DataSource)
	out.Description = types.StringPointerValue(v.Description)
	if out.Description.ValueString() == "" {
		out.Description = types.StringNull()
		// A configured "" and an omitted value both read back as "". The prior
		// is the plan or the state, so a configured empty string stays "".
		if prior != nil && !prior.Description.IsNull() && !prior.Description.IsUnknown() && prior.Description.ValueString() == "" {
			out.Description = types.StringValue("")
		}
	}
	out.Id = types.StringPointerValue(&v.Id)
	out.LogsQuery = flattenV2LogsQuery(ctx, p.AtName("logs_query"), v.LogsQuery, diags)
	out.MetricFields = types.MapNull(types.ObjectType{AttrTypes: v2MetricFieldAttrTypes()})
	// The API returns an empty list for no items; the released resource reads null.
	if len(v.MetricFields) != 0 {
		items := make(map[string]V2MetricFieldModel, len(v.MetricFields))
		for i := range v.MetricFields {
			k := v.MetricFields[i].TargetBaseMetricName
			items[k] = *flattenV2MetricField(ctx, p.AtName("metric_fields").AtMapKey(k), &v.MetricFields[i], diags)
		}
		out.MetricFields = flattenMap(ctx, types.ObjectType{AttrTypes: v2MetricFieldAttrTypes()}, items, diags)
	}
	out.MetricLabels = types.MapNull(types.StringType)
	// The API returns an empty list for no items; the released resource reads null.
	if len(v.MetricLabels) != 0 {
		items := make(map[string]string, len(v.MetricLabels))
		for _, item := range v.MetricLabels {
			items[item.TargetLabel] = item.SourceField
		}
		out.MetricLabels = flattenMap(ctx, types.StringType, items, diags)
	}
	out.Name = types.StringPointerValue(&v.Name)
	out.Permutations = types.ObjectNull(e2MPermutationsAttrTypes())
	if nested := flattenE2MPermutations(ctx, p.AtName("permutations"), v.Permutations, diags); nested != nil {
		value, valueDiags := types.ObjectValueFrom(ctx, e2MPermutationsAttrTypes(), *nested)
		diags.Append(valueDiags...)
		out.Permutations = value
	}
	out.SpansQuery = flattenV2SpansQuery(ctx, p.AtName("spans_query"), v.SpansQuery, diags)
	return out
}

// valueOf returns the value of p, or the zero value for nil. It fills an SDK
// field that is a value, not a pointer.
func valueOf[T any](p *T) T {
	var zero T
	if p == nil {
		return zero
	}
	return *p
}

